package com.riccardopinato.omnicleaner.gallery

import android.app.Activity
import android.media.MediaPlayer
import android.net.Uri
import android.os.Build
import android.view.Gravity
import android.widget.FrameLayout
import android.widget.VideoView
import androidx.test.platform.app.InstrumentationRegistry
import java.io.File
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicReference
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Read-only Android media-pipeline probe. Asset generated by pinned CI FFmpeg;
 * independent of Maestro screenshot capture of native SurfaceView layers.
 * Does not delete or modify MediaStore/user media and never initiates cleanup.
 */
class NativeVideoPlaybackInstrumentedTest {
    @Test fun syntheticH264ActuallyRendersAndAdvancesPlaybackPosition() {
        val instrumentation = InstrumentationRegistry.getInstrumentation()
        val target = instrumentation.targetContext
        val emulator = Build.HARDWARE == "ranchu" ||
            Build.HARDWARE == "goldfish" ||
            Build.FINGERPRINT.contains("emulator", ignoreCase = true) ||
            Build.PRODUCT.contains("sdk_gphone")
        assertTrue("Only disposable emulator video QA is authorized", emulator)

        val clip = File.createTempFile("omni-native-video-", ".mp4", target.cacheDir)
        val activityRef = AtomicReference<Activity>()
        val videoRef = AtomicReference<VideoView>()
        val prepared = CountDownLatch(1)
        val rendered = CountDownLatch(1)
        val failure = AtomicReference<String>()
        try {
            instrumentation.context.assets.open("omni-native-playback.mp4").use { stream ->
                clip.outputStream().use { output -> stream.copyTo(output) }
            }
            assertTrue("Synthetic video missing", clip.isFile && clip.length() > 10_000L)

            val launchIntent = requireNotNull(
                target.packageManager.getLaunchIntentForPackage(target.packageName)
            ) { "Debug app launcher intent is unavailable" }
            launchIntent.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK)
            val activity = instrumentation.startActivitySync(launchIntent)
            activityRef.set(activity)
            instrumentation.waitForIdleSync()

            instrumentation.runOnMainSync {
                val root = activity.findViewById<FrameLayout>(android.R.id.content)
                val video = VideoView(activity)
                videoRef.set(video)
                root.addView(
                    video,
                    FrameLayout.LayoutParams(640, 360, Gravity.CENTER)
                )
                video.setOnPreparedListener {
                    prepared.countDown()
                    video.start()
                }
                video.setOnInfoListener { _, code, _ ->
                    if (code == MediaPlayer.MEDIA_INFO_VIDEO_RENDERING_START) {
                        rendered.countDown()
                    }
                    false
                }
                video.setOnErrorListener { _, what, extra ->
                    failure.set("MediaPlayer OnError what=$what extra=$extra")
                    true
                }
                video.setVideoURI(Uri.fromFile(clip))
                video.start()
            }

            assertTrue("H264 prepare timeout/error: ${failure.get()}", prepared.await(20, TimeUnit.SECONDS))
            assertTrue("No native rendered-frame callback: ${failure.get()}", rendered.await(20, TimeUnit.SECONDS))
            Thread.sleep(500)
            var position1 = -1
            var isPlaying1 = false
            instrumentation.runOnMainSync {
                val video = requireNotNull(videoRef.get())
                position1 = video.currentPosition
                isPlaying1 = video.isPlaying
            }
            Thread.sleep(1500)
            var position2 = -1
            var isPlaying2 = false
            instrumentation.runOnMainSync {
                val video = requireNotNull(videoRef.get())
                position2 = video.currentPosition
                isPlaying2 = video.isPlaying
            }
            assertTrue("Playback reported MediaPlayer failure: ${failure.get()}", failure.get() == null)
            assertTrue("Media not playing in both samples", isPlaying1 && isPlaying2)
            assertTrue("Video position did not advance: $position1 -> $position2", position2 >= position1 + 600)
            // Instrumentation println goes to device stdout/logcat, not to the
            // host's 'am instrument -w' result file. Emit an explicit Android
            // logcat record so CI can verify actual player metrics separately.
            android.util.Log.i(
                "OMNI_VIDEO_NATIVE_RENDER_PASS",
                "position1=$position1 position2=$position2 assetBytes=${clip.length()}",
            )
        } finally {
            val activity = activityRef.get()
            if (activity != null) {
                instrumentation.runOnMainSync {
                    videoRef.get()?.let { video ->
                        video.stopPlayback()
                        (video.parent as? FrameLayout)?.removeView(video)
                    }
                }
            }
            // Delete only this known app-private synthetic file.
            assertTrue("Synthetic QA clip cleanup", clip.delete())
        }
    }
}
